import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Introduction & Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),i={name:"guide/getting-started.md"};function r(s,e,l,d,c,g){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction-philosophy" tabindex="-1">Introduction &amp; Philosophy <a class="header-anchor" href="#introduction-philosophy" aria-label="Permalink to &quot;Introduction &amp; Philosophy&quot;">​</a></h1><h2 id="what-is-myelin" tabindex="-1">What is Myelin? <a class="header-anchor" href="#what-is-myelin" aria-label="Permalink to &quot;What is Myelin?&quot;">​</a></h2><p><strong>Myelin (<code>.myl</code>)</strong> is a capability-safe, flat-SSA, zero-garbage-collection systems programming language designed from first principles:</p><ul><li><strong>Written by Large Language Models (LLMs)</strong> with minimal token overhead and deterministic grammar.</li><li><strong>Executed at bare-metal speed</strong> by microsecond compilers, zero-dependency runtimes, and register VMs.</li><li><strong>Audited by humans</strong> without reading thousands of lines of generated code.</li></ul><p>In neurobiology, <em>myelin</em> forms an insulating sheath around nerve fibers, eliminating signal leakage and accelerating neural impulse transmission by up to 100x. In software engineering, <strong>Myelin</strong> eliminates decades of human-ergonomic ceremony between neural reasoning and silicon execution.</p><hr><h2 id="the-human-language-bottleneck" tabindex="-1">The Human-Language Bottleneck <a class="header-anchor" href="#the-human-language-bottleneck" aria-label="Permalink to &quot;The Human-Language Bottleneck&quot;">​</a></h2><p>Mainstream programming languages (C#, TypeScript, Python, Rust, Go) were built for human biological constraints:</p><ul><li>60-WPM mechanical keyboards</li><li>Visual curly brace matching (<code>{ ... }</code>)</li><li>Complex nesting and prose compiler errors</li><li>Implicit runtime authority (functions can secretly access the network, file system, or system clock)</li></ul><p>When autonomous coding agents write code in these languages, those human conveniences become critical flaws:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Problem in Classic Languages</th><th style="text-align:left;">How Myelin Solves It</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>55–65% Token Waste:</strong> Closing braces, boilerplate keywords (<code>function</code>, <code>return</code>, <code>public static void</code>), verbose error handling.</td><td style="text-align:left;"><strong>Flat Line-SSA &amp; Token Alignment:</strong> Every symbol is optimized for modern LLM BPE tokenizers. No trailing closing braces.</td></tr><tr><td style="text-align:left;"><strong>Hidden Side-Effects:</strong> Functions secretly making network calls, deleting files, or leaking memory.</td><td style="text-align:left;"><strong>Zero Ambient Authority:</strong> Pure by default. All side effects require explicit capability flags (<code>!net</code>, <code>!db</code>, <code>!fs</code>).</td></tr><tr><td style="text-align:left;"><strong>Context Window Exhaustion on Compiler Errors:</strong> 20-line Rust/C++ error messages pollute LLM context.</td><td style="text-align:left;"><strong>Single-Line Diagnostic Wire (<code>--llm</code>):</strong> Precise single-line repair instructions that agents can parse in 1 token step.</td></tr><tr><td style="text-align:left;"><strong>Human Review Burnout:</strong> Humans cannot safely review 10,000 lines of generated code every hour.</td><td style="text-align:left;"><strong>Trust &amp; Capability Manifest (<code>myelinc audit</code>):</strong> Humans inspect verified capabilities and contracts, not lines of code.</td></tr></tbody></table><hr><h2 id="core-guarantees" tabindex="-1">Core Guarantees <a class="header-anchor" href="#core-guarantees" aria-label="Permalink to &quot;Core Guarantees&quot;">​</a></h2><ol><li><strong>Deterministic LL(1) Parsing:</strong> Every top-level item begins with <code>#</code> at column 0. Every control flow statement begins with <code>@</code>. There is never an ambiguous parsing state.</li><li><strong>2-Space Indentation Grammar:</strong> Tabs are strictly forbidden (<code>E001</code>). Indentation must always be multiples of 2 spaces.</li><li><strong>Zero Null &amp; Zero Unchecked Exceptions:</strong> Optionality (<code>?T</code>) and failure (<code>T!E</code>) are first-class value types with single-character operators (<code>?</code>, <code>^</code>).</li><li><strong>Driverless Embedded Runtime:</strong> Includes a native embedded key-value database and HTTP server without pulling in gigabytes of <code>node_modules</code> or complex C libraries.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Proceed to <a href="/guide/installation">Installation &amp; Toolchain</a> to install <code>myelinc</code> and run your first Myelin program.</li><li>Explore the <a href="/guide/syntax-guide">Syntax Guide</a> to understand the core directives and statement forms.</li></ul>',17)])])}const h=t(i,[["render",r]]);export{m as __pageData,h as default};
